# cc-P760 (generated by make_shots.py): opens the Achievement store and asks for shots of the window and its confirm step.
import API

SIG = r"D:/UO/golems/Iron/p760-proof/apstore-signal.txt"
LOG = r"D:/UO/golems/Iron/p760-proof/apstore.log"


def note(text):
    with open(LOG, "a") as f:
        f.write(text + "\n")
    API.SysMsg("P760: " + text)


def shot(name):
    with open(SIG, "a") as f:
        f.write("SHOT " + name + "\n")
    API.Pause(2)


API.Pause(4)
note("opening the Achievement store with: [apstore")
API.Msg("[apstore")
API.Pause(4)
shot("apstore-window")
API.ReplyGump(209)
API.Pause(4)
shot("apstore-confirm")
if True:
    API.ReplyGump(1)
    API.Pause(4)
    shot("apstore-after-buy")
note("done")
with open(SIG, "a") as f:
    f.write("DONE\n")
